import{_ as t,o,c as a,a2 as s}from"./chunks/framework.BiXHgXAn.js";const g=JSON.parse('{"title":"Contributing","description":"Comprehensive guide for contributing to the Task project, including setup, development, testing, and submitting PRs","frontmatter":{"title":"Contributing","description":"Comprehensive guide for contributing to the Task project, including setup, development, testing, and submitting PRs","section":"Contributing","docType":"contributing","outline":"deep"},"headers":[],"relativePath":"docs/contributing.md","filePath":"next/docs/contributing.md"}'),n={name:"docs/contributing.md"};function i(r,e,d,c,l,h){return o(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="contributing" tabindex="-1">Contributing <a class="header-anchor" href="#contributing" aria-label="Permalink to &quot;Contributing&quot;">​</a></h1><p>Thank you for your interest in contributing to Task! We welcome and appreciate all forms of contributions, but we kindly ask that you read this document first. If you have any questions that were not answered by this document, you can reach out on our <a href="https://discord.gg/6TY36E39UK" target="_blank" rel="noreferrer">Discord</a> or by opening a discussion on GitHub. If you want to help, but you&#39;re not sure where to start, you can check out our list of <a href="https://github.com/go-task/task/contribute" target="_blank" rel="noreferrer">good first issues</a>.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>This document applies to the core <a href="https://github.com/go-task/task" target="_blank" rel="noreferrer">Task</a> repository <em>and</em> <a href="https://github.com/go-task/vscode-task" target="_blank" rel="noreferrer">Task for Visual Studio Code</a>.</p></div><h2 id="ai-usage-policy" tabindex="-1">AI Usage Policy <a class="header-anchor" href="#ai-usage-policy" aria-label="Permalink to &quot;AI Usage Policy&quot;">​</a></h2><p>When using AI tools (including LLMs like ChatGPT, Claude, Copilot, etc.) to contribute to Task:</p><ul><li><strong>Please disclose AI usage</strong> to reduce maintainer fatigue</li><li><strong>You are responsible</strong> for all AI-generated issues or PRs you submit</li><li><strong>Low-quality or unreviewed AI content will be closed immediately</strong></li><li><strong>Keep conversations human</strong> - PR descriptions, review comments, and issue discussions should be written in your own words, not generated by AI. Code review is a discussion between people, not bots.</li></ul><p>We encourage the use of AI tools to assist with development, but all contributions must be thoroughly reviewed and tested by the contributor before submission. AI-generated code should be understood, validated, and adapted to meet Task&#39;s standards.</p><h2 id="before-you-start" tabindex="-1">Before you start <a class="header-anchor" href="#before-you-start" aria-label="Permalink to &quot;Before you start&quot;">​</a></h2><ul><li><strong>Check existing work</strong> - Is there an existing PR? Are there issues discussing the feature/change you want to make? Please make sure you consider/address these discussions in your work.</li><li><strong>Backwards compatibility</strong> - Will your change break existing Taskfiles? It is much more likely that your change will merged if it backwards compatible. Is there an approach you can take that maintains this compatibility? If not, consider opening an issue first so that API changes can be discussed before you invest your time into a PR.</li><li><strong>Experiments</strong> - If there is no way to make your change backward compatible then there is a procedure to introduce breaking changes into minor versions. We call these &quot;<a href="./experiments/">experiments</a>&quot;. If you&#39;re intending to work on an experiment, then please read the <a href="./experiments/#workflow">experiments workflow</a> document carefully and submit a proposal first.</li></ul><h2 id="_1-setup" tabindex="-1">1. Setup <a class="header-anchor" href="#_1-setup" aria-label="Permalink to &quot;1. Setup&quot;">​</a></h2><p>The easiest way to install everything you need to work on Task is <a href="https://mise.jdx.dev" target="_blank" rel="noreferrer">mise</a>. From the repository root, run:</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mise</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span></code></pre></div><p>This installs the pinned versions of Go, Node.js, pnpm and the dev tools (<code>golangci-lint</code>, <code>mockery</code>, <code>gotestsum</code>, <code>goreleaser</code> and <code>gorelease</code>) declared in the <code>mise.toml</code> file.</p><p>If you&#39;d rather install things manually, you&#39;ll need:</p><ul><li><strong>Go</strong> - Task is written in <a href="https://go.dev" target="_blank" rel="noreferrer">Go</a>. We always support the latest two major Go versions, so make sure your version is recent enough.</li><li><strong>Node.js</strong> - <a href="https://nodejs.org/en/" target="_blank" rel="noreferrer">Node.js</a> is used to host Task&#39;s documentation server and is required if you want to run this server locally. It is also required if you want to contribute to the Visual Studio Code extension.</li><li><strong>Pnpm</strong> - <a href="https://pnpm.io/" target="_blank" rel="noreferrer">Pnpm</a> is the Node.js package manager used by Task.</li></ul><h2 id="_2-making-changes" tabindex="-1">2. Making changes <a class="header-anchor" href="#_2-making-changes" aria-label="Permalink to &quot;2. Making changes&quot;">​</a></h2><ul><li><strong>Code style</strong> - Try to maintain the existing code style where possible. Go code should be formatted and linted by <a href="https://golangci-lint.run" target="_blank" rel="noreferrer"><code>golangci-lint</code></a>. This wraps the <a href="https://github.com/mvdan/gofumpt" target="_blank" rel="noreferrer"><code>gofumpt</code></a> and <a href="https://github.com/daixiang0/gci" target="_blank" rel="noreferrer"><code>gci</code></a> formatters and a number of linters. We recommend that you take a look at the <a href="https://golangci-lint.run/welcome/integrations/" target="_blank" rel="noreferrer">golangci-lint docs</a> for a guide on how to setup your editor to auto-format your code. Any Markdown or TypeScript files should be formatted and linted by <a href="https://prettier.io" target="_blank" rel="noreferrer">Prettier</a>. This style is enforced by our CI to ensure that we have a consistent style across the project. You can use the <code>task lint</code> command to lint the code locally and the <code>task lint:fix</code> command to try to automatically fix any issues that are found. You can also use the <code>task fmt</code> command to auto-format the files if your editor doesn&#39;t do it for you.</li><li><strong>Documentation</strong> - Ensure that you add/update any relevant documentation. See the <a href="#updating-documentation">updating documentation</a> section below.</li><li><strong>Tests</strong> - Ensure that you add/update any relevant tests and that all tests are passing before submitting the PR. See the <a href="#writing-tests">writing tests</a> section below.</li></ul><h3 id="running-your-changes" tabindex="-1">Running your changes <a class="header-anchor" href="#running-your-changes" aria-label="Permalink to &quot;Running your changes&quot;">​</a></h3><p>To run Task with working changes, you can use <code>go run ./cmd/task</code>. To run a development build of task against a test Taskfile in <code>testdata</code>, you can use <code>go run ./cmd/task --dir ./testdata/&lt;my_test_dir&gt; &lt;task_name&gt;</code>.</p><p>To run Task for Visual Studio Code, you can open the project in VSCode and hit F5 (or whatever you debug keybind is set to). This will open a new VSCode window with the extension running. Debugging this way is recommended as it will allow you to set breakpoints and step through the code. Otherwise, you can run <code>task package</code> which will generate a <code>.vsix</code> file that can be used to manually install the extension.</p><h3 id="updating-documentation" tabindex="-1">Updating documentation <a class="header-anchor" href="#updating-documentation" aria-label="Permalink to &quot;Updating documentation&quot;">​</a></h3><p>Task uses <a href="https://vitepress.dev" target="_blank" rel="noreferrer">Vitepress</a> to host a documentation server. The code for this is located in the core Task repository. This can be setup and run locally by using <code>task website</code> (requires <code>nodejs</code> &amp; <code>pnpm</code>). All content is written in Markdown and is located in the <code>website/src</code> directory. All Markdown documents should have an 80 character line wrap limit (enforced by Prettier).</p><p>Search is provided by Algolia DocSearch. The crawler runs on Algolia&#39;s side and is configured through their dashboard, but <code>website/docsearch.config.js</code> holds the same configuration in the repository so it can be read and reviewed. If you change one, change the other. A page&#39;s <code>section:</code> frontmatter is what the crawler shows as the breadcrumb on a search result, while <code>docType:</code> powers its search facet, so a new page needs both.</p><p>After building the site, run <code>pnpm check:links</code> from <code>website/</code> to check links in the generated Markdown pages and LLM indexes. The LLM plugin is patched in <code>website/patches/</code> to resolve links before it moves directory indexes such as <code>docs/guide/index.md</code> to <code>docs/guide.md</code>. When upgrading the plugin, retain the patch until upstream handles those links, and check both documentation channels.</p><p>When making a change, consider whether a change to the <a href="./guide/">Usage Guide</a> is necessary. This document contains descriptions and examples of how to use Task features. If you&#39;re adding a new feature, try to find an appropriate place to add a new section. If you&#39;re updating an existing feature, ensure that the documentation and any examples are up-to-date. Ensure that any examples follow the <a href="./styleguide">Taskfile Styleguide</a>.</p><p>If you added a new command or flag, ensure that you add it to the <a href="./reference/cli">CLI Reference</a>. New fields also need to be added to the <a href="./reference/schema">Schema Reference</a> and <a href="https://github.com/go-task/task/blob/main/website/src/public/schema.json" target="_blank" rel="noreferrer">JSON Schema</a>. The descriptions for fields in the docs and the schema should match.</p><h4 id="documentation-channels" tabindex="-1">Documentation channels <a class="header-anchor" href="#documentation-channels" aria-label="Permalink to &quot;Documentation channels&quot;">​</a></h4><p>The docs, the blog and the coding-agent guide exist in two copies, so that taskfile.dev never announces a feature that is not in the released binary yet:</p><table tabindex="0"><thead><tr><th>Directory</th><th>Channel</th><th>Published on</th></tr></thead><tbody><tr><td><code>website/src/next/{docs,blog}</code></td><td><code>next</code></td><td>next.taskfile.dev</td></tr><tr><td><code>website/src/latest/{docs,blog}</code></td><td><code>latest</code></td><td>taskfile.dev</td></tr></tbody></table><p>The coding-agent guide follows the same channels as <code>src/next/agents.md</code> and <code>src/latest/agents.md</code>, and is promoted at release time too.</p><p>Everything else - the homepage, the team, adopters, images - is shared by both channels and goes live as soon as the site is deployed.</p><p><strong>Write in <code>website/src/next</code>.</strong> It holds the upcoming release, and <code>cmd/release</code> copies it over <code>website/src/latest</code> at every release. The same split applies to the JSON schemas: edit <code>next-schema.json</code> and <code>next-schema-taskrc.json</code>, never <code>schema.json</code> or <code>schema-taskrc.json</code>.</p><p>Where you put a blog post decides when it goes out. A post that announces a feature belongs in <code>website/src/next/blog</code> alone: it ships with the release that carries the feature. A post that stands on its own - an announcement, a write-up about an already released feature - can be added to <code>website/src/latest/blog</code> as well, and it goes live at the next deploy. Its sidebar entry comes from the post&#39;s own frontmatter, so there is nothing else to update.</p><p>Never edit an existing file under <code>website/src/latest</code>: <code>cmd/release</code> overwrites that directory at every release, so the change would be silently lost. The same goes for <code>.vitepress/sidebar/latest.ts</code>, which is promoted from <code>next.ts</code>. CI fails a pull request that modifies either. Adding a file under <code>website/src/latest</code> is fine - that is how a blog post gets published early.</p><p>To preview what taskfile.dev will look like, run <code>task website:start:latest</code>. It serves the <code>latest</code> channel on port 3002, so it can run next to <code>task website</code> and the version selector switches between the two.</p><h3 id="writing-tests" tabindex="-1">Writing tests <a class="header-anchor" href="#writing-tests" aria-label="Permalink to &quot;Writing tests&quot;">​</a></h3><p>A lot of Task&#39;s tests are held in the <code>task_test.go</code> file in the project root and this is where you&#39;ll most likely want to add new ones too. Most of these tests also have a subdirectory in the <code>testdata</code> directory where any Taskfiles/data required to run the tests are stored.</p><p>When making a changes, consider whether new tests are required. These tests should ensure that the functionality you are adding will continue to work in the future. Existing tests may also need updating if you have changed Task&#39;s behavior.</p><p>You may also consider adding unit tests for any new functions you have added. The unit tests should follow the Go convention of being location in a file named <code>*_test.go</code> in the same package as the code being tested.</p><h2 id="_3-committing-your-code" tabindex="-1">3. Committing your code <a class="header-anchor" href="#_3-committing-your-code" aria-label="Permalink to &quot;3. Committing your code&quot;">​</a></h2><p>Try to write meaningful commit messages and avoid having too many commits on the PR. Most PRs should likely have a single commit (although for bigger PRs it may be reasonable to split it in a few). Git squash and rebase is your friend!</p><p>If you&#39;re not sure how to format your commit message, check out <a href="https://www.conventionalcommits.org" target="_blank" rel="noreferrer">Conventional Commits</a>. This style is not enforced, but it is a good way to make your commit messages more readable and consistent.</p><h2 id="_4-submitting-a-pr" tabindex="-1">4. Submitting a PR <a class="header-anchor" href="#_4-submitting-a-pr" aria-label="Permalink to &quot;4. Submitting a PR&quot;">​</a></h2><ul><li><strong>Describe your changes</strong> - Ensure that you provide a comprehensive description of your changes.</li><li><strong>Issue/PR links</strong> - Link any previous work such as related issues or PRs. Please describe how your changes differ to/extend this work.</li><li><strong>Examples</strong> - Add any examples or screenshots that you think are useful to demonstrate the effect of your changes.</li><li><strong>Draft PRs</strong> - If your changes are incomplete, but you would like to discuss them, open the PR as a draft and add a comment to start a discussion. Using comments rather than the PR description allows the description to be updated later while preserving any discussions.</li></ul><h2 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;FAQ&quot;">​</a></h2><blockquote><p>I want to contribute, where do I start?</p></blockquote><p>Take a look at the list of <a href="https://github.com/go-task/task/issues" target="_blank" rel="noreferrer">open issues for Task</a> or <a href="https://github.com/go-task/vscode-task/issues" target="_blank" rel="noreferrer">Task for Visual Studio Code</a>. We have a <a href="https://github.com/go-task/task/issues?q=is%3Aissue+is%3Aopen+label%3A%22good+first+issue%22" target="_blank" rel="noreferrer">good first issue</a> label for simpler issues that are ideal for first time contributions.</p><p>All kinds of contributions are welcome, whether its a typo fix or a shiny new feature. You can also contribute by upvoting/commenting on issues, helping to answer questions or contributing to other <a href="./community">community projects</a>.</p><blockquote><p>I&#39;m stuck, where can I get help?</p></blockquote><p>If you have questions, feel free to ask them in the <code>#help</code> forum channel on our <a href="https://discord.gg/6TY36E39UK" target="_blank" rel="noreferrer">Discord server</a> or open a <a href="https://github.com/go-task/task/discussions" target="_blank" rel="noreferrer">Discussion</a> on GitHub.</p><hr>',51)])])}const p=t(n,[["render",i]]);export{g as __pageData,p as default};
